import React, { useState, useEffect, useMemo } from 'react';
import { fetchAllApplicants } from './api/apiClient';
import './index.css';

function RecruiterDashboard({ token }) {
  const [applicants, setApplicants] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [experienceFilter, setExperienceFilter] = useState('');

  const loadApplicants = async () => {
    setLoading(true);
    setError('');
    try {
      const params = {
        search: searchTerm,
        min_exp: experienceFilter || 0,
      };
      const res = await fetchAllApplicants(token, params);
      setApplicants(res.data);
    } catch (err) {
      setError('Failed to fetch applicants.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadApplicants();
  }, [token, searchTerm, experienceFilter]);

  const filteredApplicants = applicants;

  return (
    <div className="dashboard-container">
      <h2>Recruiter Dashboard</h2>
      <p>Welcome, Recruiter! Here you can view and manage applicants.</p>
      
      <div className="recruiter-actions">
        <button onClick={loadApplicants} disabled={loading}>
          {loading ? 'Refreshing...' : 'Refresh Applicants'}
        </button>
        <input
          type="text"
          placeholder="Search by keyword..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ marginRight: 8 }}
        />
        <input
          type="number"
          placeholder="Min Experience (years)"
          value={experienceFilter}
          onChange={(e) => setExperienceFilter(e.target.value)}
        />
      </div>

      {error && <div style={{ color: 'red' }}>{error}</div>}
      
      <div className="applicant-list">
        {filteredApplicants.length > 0 ? (
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>LinkedIn</th>
                <th>Rating</th>
                <th>Experience (Yrs)</th>
                <th>Summary</th>
              </tr>
            </thead>
            <tbody>
              {filteredApplicants.map((applicant) => (
                <tr key={applicant.id}>
                  <td>{applicant.name}</td>
                  <td>{applicant.email}</td>
                  <td>
                    <a href={applicant.linkedin_url} target="_blank" rel="noopener noreferrer">
                      Profile
                    </a>
                  </td>
                  <td>{applicant.insights?.rating || 'N/A'}</td>
                  <td>{applicant.insights?.experience_years || 'N/A'}</td>
                  <td>{applicant.insights?.summary || 'N/A'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No applicants match your criteria.</p>
        )}
      </div>
    </div>
  );
}

export default RecruiterDashboard;
